import React, { useState } from 'react';

export default function Timetable({ onTeacherClick }) {
  const [selectedGrade, setSelectedGrade] = useState('Grade 11');

  const classData = {
    "Grade 6": [
      { subject: "Mathematics (ගණිතය)", time: "Monday 3.00 PM - 5.00 PM", teacher: "Buddhika Darshani" }
    ],
    "Grade 8": [
      { subject: "Mathematics (ගණිතය)", time: "Tuesday 4.30 PM - 6.30 PM", teacher: "Buddhika Darshani" }
    ],
    "Grade 9": [
      { subject: "English (ඉංග්‍රීසි)", time: "Monday 3.30 PM - 5.00 PM", teacher: "Ranga Rajapaksha" },
      { subject: "Sinhala (සිංහල)", time: "Tuesday 3.00 PM - 5.00 PM", teacher: "Sajith Gunaratne" }
    ],
    "Grade 10": [
      { subject: "Sinhala (සිංහල)", time: "Monday 3.30 PM - 6.00 PM", teacher: "Sajith Gunaratne" },
      { subject: "History (ඉතිහාසය)", time: "Tuesday 3.00 PM - 6.00 PM", teacher: "Chamara Rajapaksha" }
    ],
    "Grade 11": [
      { subject: "Mathematics (ගණිතය)", time: "Monday 4.00 PM - 6.00 PM", teacher: "Nalinda Jayasinghe" },
      { subject: "Commerce (වාණිජ්‍යය)", time: "Tuesday 2.30 PM - 4.30 PM", teacher: "Chamara Rajapaksha" }
    ],
    "A/L 2026": [
      { subject: "ICT (Information Technology)", time: "Monday 5.00 PM - 7.00 PM", teacher: "Chamika Jayaweera" },
      { subject: "Business Studies (BS)", time: "Thursday 8.00 AM - 11.00 AM", teacher: "Chamara Rajapaksha" },
      { subject: "Accounting (Theory)", time: "Friday 8.00 AM - 12.00 PM", teacher: "Prasiddha Dissanayake" },
      { subject: "Accounting (Paper)", time: "Friday 1.00 PM - 5.00 PM", teacher: "Prasiddha Dissanayake" },
      { subject: "Physics", time: "Friday 8.00 AM - 2.00 PM", teacher: "Manoj Salinda" }
    ],
    "A/L 2027": [
      { subject: "Accounting", time: "Friday 11.00 AM - 1.00 PM", teacher: "Prasiddha Dissanayake" },
      { subject: "Business Studies (BS)", time: "Friday 8.00 AM - 10.00 AM", teacher: "Chamara Rajapaksha" }
    ]
  };

  const grades = ["Grade 6", "Grade 8", "Grade 9", "Grade 10", "Grade 11", "A/L 2026", "A/L 2027"];

  return (
    <div style={{ padding: '60px 20px', maxWidth: '1200px', margin: '0 auto' }}>
      <h2 style={{ textAlign: 'center', color: '#1e3a8a', marginBottom: '10px', fontSize: '28px', fontWeight: 'bold' }}>Find Your Classes</h2>
      <p style={{ textAlign: 'center', color: '#666', marginBottom: '40px' }}>Select your grade to view full subject details and schedules.</p>
      
      <div style={{ display: 'flex', justifyContent: 'center', gap: '10px', flexWrap: 'wrap', marginBottom: '40px' }}>
        {grades.map(grade => (
          <button 
            key={grade}
            onClick={() => setSelectedGrade(grade)}
            style={{
              padding: '12px 22px', borderRadius: '25px', border: 'none', fontWeight: 'bold', cursor: 'pointer', fontSize: '14px',
              backgroundColor: selectedGrade === grade ? '#0056b3' : '#e5e7eb',
              color: selectedGrade === grade ? '#fff' : '#4b5563',
              boxShadow: selectedGrade === grade ? '0 4px 12px rgba(0,86,179,0.2)' : 'none',
              transition: 'all 0.2s'
            }}
          >
            {grade}
          </button>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '25px' }}>
        {classData[selectedGrade]?.map((item, idx) => (
          <div key={idx} style={{ backgroundColor: '#fff', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', borderTop: '5px solid #0056b3' }}>
            <span style={{ fontSize: '11px', fontWeight: 'bold', backgroundColor: '#e0f2fe', color: '#0369a1', padding: '4px 10px', borderRadius: '10px' }}>{selectedGrade}</span>
            <h3 style={{ margin: '15px 0 10px 0', fontSize: '22px', color: '#1f2937' }}>{item.subject}</h3>
            <p style={{ color: '#4b5563', fontSize: '15px', marginBottom: '20px' }}>⏰ Schedule: <strong>{item.time}</strong></p>
            <div style={{ borderTop: '1px solid #f3f4f6', paddingTop: '15px' }}>
              <span style={{ fontSize: '13px', color: '#9ca3af' }}>Lecturer</span> <br/>
              <span onClick={onTeacherClick} style={{ color: '#059669', fontWeight: 'bold', cursor: 'pointer', textDecoration: 'underline', fontSize: '16px', display: 'inline-block', marginTop: '4px' }}>
                {item.teacher}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
